function BTSequenceNode:OnUpdate(agent, blackboard)
    local count = BTNode.GetChildCount(self)
    if count == 0 then
         return BTNode.BTStatus.FINISHED
    end

    self._currentNodeIndex = math.max(self._currentNodeIndex, 1)

    for i = self._currentNodeIndex, count do
        ---@type BTNode
        local child   = BTNode.GetNode(self, i)
        local runningStatus = child:OnUpdate(agent, blackboard)
        if runningStatus ~= BTNode.BTStatus.FINISHED then
            return runningStatus
        end
        self._currentNodeIndex = self._currentNodeIndex + 1
    end

    return BTNode.BTStatus.FINISHED
end

function BTSequenceNode:OnReset(agent, blackboard)
    ---@type BTNode
    local child   = BTNode.GetNode(self, self._currentNodeIndex)
    if child then
        child:OnReset(agent, blackboard)
    end
    self._currentNodeIndex = -1
end

